import torch

def run(grad_output, p_attn, mask, dropout_mask, p_dropout=0.0):
    grad_scores = grad_output * p_attn
    sum_grad = grad_scores.sum(dim=-1, keepdim=True)
    grad_scores = grad_scores - p_attn * sum_grad
    if mask is not None:
        grad_scores = grad_scores * mask.to(grad_scores.dtype)
    if dropout_mask is not None and p_dropout > 0:
        grad_scores = grad_scores * dropout_mask.to(grad_scores.dtype) / (1.0 - p_dropout)
    return grad_scores
